class Base
{
    public Base() { Console.WriteLine($"Base: {Describe()}"); }
    public virtual string Describe() => "base";
}
class Derived : Base
{
    private readonly string _text;
    public Derived(string text)
    {
        _text = text;
        Console.WriteLine($"Derived: {Describe()}");
    }
    public override string Describe() => $"text={_text ?? "null"}";
}

