Console.WriteLine(Route("GET api orders"));
Console.WriteLine(Route("DELETE api orders 7"));
Console.WriteLine(Route(""));

static string Route(string request)
{
    string[] p = request.Split(' ', StringSplitOptions.RemoveEmptyEntries);
    return p switch
    {
        ["GET", "api", "orders"] => "list",
        ["GET", "api", "orders", var id] => $"detail {id}",
        [var m, ..] => $"unsupported {m}",
        [] => "empty"
    };
}

